  "user"."id" = $1
returning
  *

-- PersonRepository.reassignCluster
begin
update "person_group"
set
  "clusterGroupId" = $1
where
  "person_group"."id" in (
    select
      "person"."personGroupId"
    from
      "person"
    where
      "person"."ownerId" = $2
  )
  and not exists (
    select
      "person"."personGroupId"
    from
      "person"
    where
      "person"."personGroupId" = "person_group"."id"
      and "person"."ownerId" != $3
  )
with
  "shared" as (
    select distinct
      "person"."personGroupId" as "oldId"
    from
      "person"
    where
      "person"."ownerId" = $1
      and exists (
        select
          "other"."personGroupId"
        from
          "person" as "other"
        where
          "other"."personGroupId" = "person"."personGroupId"
          and "other"."ownerId" != $2
      )
  ),
  "mapping" as materialized (
    select
      "shared"."oldId",
      uuid_generate_v4 () as "newId"
    from
      "shared"
  ),
  "created" as (
    insert into
      "person_group" ("id", "clusterGroupId")
    select
      "mapping"."newId",
      $3 as "clusterGroupId"
    from
      "mapping"
  )
select
  "mapping"."oldId",
  "mapping"."newId"
from
  "mapping"
commit

