-- PersonRepository.getFacesByIds
select
  "asset_face".*,
  (
    select
      to_json(obj)
    from
      (
        select
          "person".*,
          (
            select
              coalesce(json_agg(agg), '[]')
            from
              (
                select
                  "person_user"."sharedById",
                  "person_user"."role",
                  "other"."name",
                  "other"."birthDate"
                from
                  "person" as "other"
                  inner join "person_user" on "person_user"."personGroupId" = "other"."personGroupId"
                  and "person_user"."sharedById" = "other"."ownerId"
                  and "person_user"."sharedWithId" = $1
                where
                  "other"."personGroupId" = "person"."personGroupId"
                  and (
                    "other"."birthDate" is not null
                    or "other"."name" != $2
                  )
              ) as agg
          ) as "otherPeople",
          (
            select
              coalesce(json_agg(agg), '[]')
            from
              (
                select
                  "id",
                  "name",
                  "email",
                  "avatarColor",
                  "profileImagePath",
                  "profileChangedAt",
                  "person_user"."role"
                from
                  "person_user"
                  inner join "user" on "user"."id" = "person_user"."sharedById"
                  and "user"."deletedAt" is null
                where
                  "person_user"."personGroupId" = "person"."personGroupId"
                  and "person_user"."sharedWithId" = $3
                order by
                  "user"."name"
              ) as agg
          ) as "sharedBy",
          (
            select
              coalesce(json_agg(agg), '[]')
            from
              (
                select
                  "id",
                  "name",
                  "email",
                  "avatarColor",
                  "profileImagePath",
                  "profileChangedAt",
                  "person_user"."role"
                from
                  "person_user"
                  inner join "user" on "user"."id" = "person_user"."sharedWithId"
                  and "user"."deletedAt" is null
                where
                  "person_user"."personGroupId" = "person"."personGroupId"
                  and "person_user"."sharedById" = $4
                order by
                  "user"."name"
              ) as agg
          ) as "sharedWith"
        from
          "person"
        where
          "person"."personGroupId" = "asset_face"."personGroupId"
          and "person"."ownerId" = $5
      ) as obj
  ) as "person"
from
  "asset_face"
where
  "asset_face"."assetId" in ($6)
  and "asset_face"."personGroupId" in ($7)
  and "asset_face"."deletedAt" is null

-- PersonRepository.getRandomFace
select
  "asset_face".*
from
  "asset_face"
where
  "asset_face"."personGroupId" = $1
  and "asset_face"."deletedAt" is null
  and "asset_face"."isVisible" is true

-- PersonRepository.getLatestFaceDate
select
  max("asset_job_status"."facesRecognizedAt")::text as "latestDate"
from
  "asset_job_status"

-- PersonRepository.deleteAssetFace
delete from "asset_face"
where
  "asset_face"."id" = $1

-- PersonRepository.softDeleteAssetFaces
update "asset_face"
set
  "deletedAt" = $1
where
  "asset_face"."id" = $2

-- PersonRepository.getForFeatureFaceUpdate
select
  "asset_face"."id"
from
  "asset_face"
  inner join "asset" on "asset"."id" = "asset_face"."assetId"
  and "asset"."isOffline" = $1
where
  "asset_face"."assetId" = $2
  and "asset_face"."personGroupId" = $3
  and "asset_face"."deletedAt" is null

-- PersonRepository.getForMergePerson
select
  "person".*
from
  "person"
where
  "person"."personGroupId" in ($1)
